mod solution;

fn main() {
    let cases = [
    (r#"[11, 8, 3, 8]"#, r#"true"#),
    (r#"[1, 2, 3]"#, r#"false"#),
    (r#"
[1, 2, 3]
"#, r#"false"#),
    (r#"  
[11, 8, 3, 8]
  "#, r#"true"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS hash-membership");
}
